#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-or-later
"""Regenerates test/fixtures/png_fixtures.h (small PNGs as C arrays) with Pillow."""
import io
import pathlib

from PIL import Image

OUT = pathlib.Path(__file__).with_name("png_fixtures.h")


def png_bytes(img: Image.Image) -> bytes:
    buf = io.BytesIO()
    img.save(buf, format="PNG", optimize=True)
    return buf.getvalue()


def rgb_2x2() -> Image.Image:
    img = Image.new("RGB", (2, 2))
    img.putdata([(255, 0, 0), (0, 255, 0), (0, 0, 255), (255, 255, 255)])
    return img


def palette_3x1() -> Image.Image:
    img = Image.new("P", (3, 1))
    img.putpalette([255, 0, 0, 0, 255, 0, 0, 0, 255] + [0] * (256 * 3 - 9))
    img.putdata([2, 1, 0])
    return img


def rgba_2x1() -> Image.Image:
    img = Image.new("RGBA", (2, 1))
    img.putdata([(255, 255, 255, 0), (200, 100, 50, 255)])
    return img


def to_c(name: str, data: bytes) -> str:
    rows = [", ".join(f"0x{b:02x}" for b in data[i:i + 16]) for i in range(0, len(data), 16)]
    body = ",\n  ".join(rows)
    return f"static const uint8_t {name}[] = {{\n  {body}\n}};\n"


def main() -> None:
    parts = [
        "// SPDX-License-Identifier: GPL-3.0-or-later\n",
        "// GENERATED by test/fixtures/gen_png_fixtures.py - do not edit.\n",
        "#pragma once\n#include <cstdint>\n\n",
        to_c("kPngRgb2x2", png_bytes(rgb_2x2())),
        to_c("kPngPalette3x1", png_bytes(palette_3x1())),
        to_c("kPngRgba2x1", png_bytes(rgba_2x1())),
    ]
    OUT.write_text("".join(parts), newline="\n")
    print(f"wrote {OUT}")


if __name__ == "__main__":
    main()
